        law: "stalking",
        spec: "Willfully harassed {V} on more than one occasion without legitimate purpose, on or about {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a new neighbor found a camera aimed at {V.his} windows and a man waiting at {V.his} workplace. {DL} says it was security.",
