    static let textsAgain = SmallCases.make(
        key: "story.followup.textsAgain",
        category: .violent,
        headlines: ["Laid-Off Worker Threatens Former Supervisor by Text", "Texter From Prior Threat Case Writes Again"],
        law: "communicatingThreats",
        spec: "Communicated a threat to {V} to cause fear, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, after being laid off, {D} sent a supervisor 15 texts saying {V.he} would 'pay.' {DL} says it was venting.",
        state: [E(.digital, 3, "Text Messages", "Fifteen threats."), E(.statement, 2, "Spouse", "Doors were locked.")],
        defense: [E(.statement, 1, "Venting", "{DL} says it was venting.")],
        role: "Supervisor",
        exam: [.direct("What is your role?", "\"I'm a supervisor at a manufacturing plant, where {DL} worked on the line until a recent layoff.\""), .direct("What did you receive?", "\"Fifteen text messages over two days from {DL}, saying I would pay for what happened and that {D.he} knew where I lived.\""), .direct("What did the texts say?", "\"'You'll pay for this,' 'I know where you park,' and 'Watch your back,' among other threats.\""), .direct("How did you react?", "\"I was scared. I told my family, and we changed our routines and locked every door at night.\""), .direct("What did your spouse do?", "\"{V.He} kept the doors locked, called the sheriff's office, and asked me to stay home from work for a few days.\""), .direct("What did {DL} say?", "\"{D.He} said it was venting and that {D.he} didn't mean any of it.\""), .cross("{DL} was laid off with others?", "\"Yes, in a group of twenty, because of a drop in orders.\""), .cross("{DL} never came to your house?", "\"No, and I haven't seen {D.him} since the layoff.\""), .cross("The texts stopped?", "\"After the deputy spoke to {D.him}, yes, they stopped, and I haven't heard from {D.him} since.\""), .cross("{DL} was upset about the layoff?", "\"Very, and {D.he} told me so at the meeting.\""), .cross("You weren't the one who decided the layoff?", "\"The decision came from management, but I delivered the news.\"")],
        theory: ("{D} threatened a supervisor.", "Venting."),
        allocution: "\"I was laid off and furious, and I sent those fifteen texts to my supervisor. I was only venting, and I never meant to hurt anyone. I've been in this room before for the same kind of anger, and I should have called a friend instead.\"",
        truths: ("{DL} had a prior case in this court.", "{DL} apologized next morning."),
        defendant: [.direct("Did you send the texts?", "\"Yes, I sent them. I was angry about losing my job and I wanted to lash out.\""), .direct("Did you mean them?", "\"No. I was venting. I never planned to hurt my supervisor or anyone else.\""), .direct("Why did you say you knew where {V.he} parks?", "\"I only meant I'd seen where {V.he} parks at work. It was a stupid thing to say.\""), .direct("What was happening in your life?", "\"I had lost my job, I had bills, and my wife was sick. I was overwhelmed.\""), .direct("What did you do when the deputy called?", "\"I stopped texting and told {OFF.him} I was sorry. I haven't contacted my supervisor since.\""), .direct("What would you tell your supervisor and {V.his} family?", "\"I'm sorry for frightening you. I'll never contact you again, and I hope you can forgive me.\""), .cross("You've been convicted of making threats before, haven't you?", "\"Yes, and I told the court I'd keep my anger under control. I didn't.\""), .cross("Fifteen texts in two days is a lot, isn't it?", "\"It is, and I understand how that feels to the person on the other end.\""), .cross("'Watch your back' sounds like a threat, doesn't it?", "\"It does, and I'm sorry I wrote it.\""), .cross("You'll delete {V.his} number?", "\"Yes, I'll delete {V.his} number today and block {V.him} so I can't send anything.\""), .cross("You'll get counseling for your anger?", "\"Yes, I'll sign up for counseling and I'll go every single week until they release me.\"")],
        openings: ("After being laid off from the plant, {D} sent {V}, a supervisor, fifteen text messages over two days saying {V.he} would pay for what happened and that {D} knew where {V} lived, and {V}'s spouse locked the doors, and {DL} had already appeared here in {PRIORDATE} over {PRIOR}.", "The defense will say it was venting after losing a job, words from a man in a bad week. {D} never came to {V}'s home."),
        closings: ("The texts say {V} would pay and that {D} knew where {V.he} lived, fifteen of them, and with {PRIOR} already on {D.his} record, {DL} knew exactly how those words would sound.", "Venting after a layoff is human, and {D} did nothing. The State must prove {D} meant the words as a real threat to {V}."),
        timeline: [(0, "8 p.m.: texts."), (1, "Arrest.")],
        identified: "Text Messages",
        mood: .wantsConviction)

    static let bombAgain = SmallCases.make(
