        ages: 18...60,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a caller said a gunman was in a mall, forcing a lockdown. A prepaid phone was traced to {D}. {DL} says it was stolen.",
        state: [E(.digital, 3, "Call Record", "A prepaid phone."), E(.video, 2, "Store Camera", "{D} buys a phone.")],
