        role: "Passerby",
        exam: [.direct("What did you find?", "\"I was walking to my car late at night and saw two small children asleep in the back seat of a parked car.\""), .direct("What time was it?", "\"About two in the morning, and it was cold, with the temperature near freezing and frost on the windows.\""), .direct("What did you do?", "\"I knocked on the window, and when neither child woke easily, I called 911 right away.\""), .direct("What condition were the children in?", "\"They were cold, with pale faces and blue lips, and one was shivering and confused.\""), .direct("What did the medical note say?", "\"Both had signs of cold exposure and needed treatment at the hospital, though they recovered.\""), .direct("Who was responsible for the children?", "\"{DL}, who returned to the car about an hour later and said {D.he} had gone out for a short time.\""), .cross("There was no adult in the car?", "\"No one at all, and the car was locked.\""), .cross("{DL} came back after the deputy arrived?", "\"Yes, {D.he} walked up while the deputy was checking the children.\""), .cross("The children were wearing coats?", "\"One had a light jacket and the other a blanket.\""), .cross("{DL} seemed upset?", "\"Yes, {D.he} was upset, though also defensive, and kept saying {D.he} had only been gone briefly.\""), .cross("{DL} said a friend was watching?", "\"That's what {D.he} told the deputy, but no one was there.\"")],
        theory: ("{D} left children.", "A friend."),
        allocution: "\"I went out that night and left a friend watching my two children, and I trusted that friend. I've been in this courtroom before about my kids, and I should have known better. I'm sorry for the fear they went through. I'll make sure they're never alone again.\"",
        truths: ("{DL} had a prior case in this court.", "A friend's text says she would come."),
        defendant: [.direct("Did you leave the children in the car?", "\"Yes, I left them. I thought a friend was going to watch them, and I was only gone for a short time.\""), .direct("Where did you go?", "\"To a friend's apartment two blocks away, to pick up something I needed. I told myself it would be quick.\""), .direct("Was your friend watching them?", "\"I thought so. She said she'd come out, and I believed her. I never checked.\""), .direct("How long were you gone?", "\"I thought about twenty minutes, but the deputy says it was an hour. I lost track of time.\""), .direct("Did you know it was that cold?", "\"I knew it was chilly, but I didn't realize it was near freezing. I should have checked.\""), .direct("What would you tell the children and their family?", "\"I'm sorry I put the children at risk. I'll never leave them alone again.\""), .cross("You've been investigated for leaving children alone before, haven't you?", "\"Yes, and I was told never to do it again. I did, and I'm deeply ashamed.\""), .cross("Two small children alone in a locked car at night is dangerous, isn't it?", "\"It is very dangerous, and anything could have happened to those children that night.\""), .cross("You didn't confirm that your friend was watching them?", "\"I didn't confirm that she would watch them, and that was entirely my mistake.\""), .cross("You'll accept parenting classes and supervision?", "\"Yes, I'll accept whatever parenting classes and supervision the court orders me to do.\""), .cross("You'll arrange proper child care?", "\"Yes, I'll arrange proper child care with family members I can trust before I go out.\"")],
